import os,shutil,difflib,json,hashlib
ROOT=Path(__file__).resolve().parents[1];WORK=Path(os.environ.get('DAV1D_CODEC_BUILD',ROOT/'.build/avif-hdr-dav1d')).resolve();SOURCE=Path(os.environ['MEDIA_CODEC_SOURCES']).resolve();OUT=WORK/'sources-100mp';PATCH=ROOT/'vendor/avif-hdr-dav1d/patches';PATCH.mkdir(parents=True,exist_ok=True)
