def change(base,name,old,new):
 p=base/name;s=p.read_text();assert old in s,f'Upstream changed: {name}';updated=s.replace(old,new);p.write_text(updated);changes.append({'file':base.name+'/'+name,'beforeSha256':hashlib.sha256(s.encode()).hexdigest(),'afterSha256':hashlib.sha256(updated.encode()).hexdigest()});return ''.join(difflib.unified_diff(s.splitlines(keepends=True),updated.splitlines(keepends=True),fromfile='a/'+base.name+'/'+name,tofile='b/'+base.name+'/'+name))
