patch+=change(d,'src/mem.c','    void *const ptr = malloc(sz + DEFAULT_ALIGN);','    if (sz > (size_t) PTRDIFF_MAX - DEFAULT_ALIGN) return NULL;\n    void *const ptr = malloc(sz + DEFAULT_ALIGN);')
