patch+=change(v,'src/read.c','static avifResult avifDecoderCreateCodecs(avifDecoder * decoder)\n{\n    avifDecoderData * data = decoder->data;\n    avifDecoderDataResetCodec(data);\n\n    if (data->source == AVIF_DECODER_SOURCE_TRACKS) {\n        // In this case, we will use at most two codec instances (one for the color planes and one for the alpha plane).\n        // Gain maps are not supported.\n        AVIF_CHECKRES(avifCodecCreateInternal(decoder->codecChoice, &decoder->data->tiles.tile[0], &decoder->diag, &data->codec));\n        data->tiles.tile[0].codec = data->codec;\n        if (data->tiles.count > 1) {\n            AVIF_CHECKRES(avifCodecCreateInternal(decoder->codecChoice, &decoder->data->tiles.tile[1], &decoder->diag, &data->codecAlpha));\n            data->tiles.tile[1].codec = data->codecAlpha;\n        }\n    } else {\n        // In this case, we will use one codec instance when there is only one tile or when all of the following conditions are\n        // met:\n        //   - The image must have exactly one layer (i.e. decoder->imageCount == 1).\n        //   - All the tiles must have the same operating point (because the codecs take operating point once at initialization\n        //     and do not allow it to be changed later).\n        //   - All the tiles must have the same value for allLayers (because the codecs take allLayers once at initialization\n        //     and do not allow it to be changed later).\n        //   - If the image has a single tile, it must not have a single tile alpha plane (in this case we will steal the planes\n        //     from the decoder, so we cannot use the same decoder for both the color and the alpha planes).\n        //   - All tiles have the same type (AV1 or AV2).\n        //   - No tile buffer access after another tile was decoded (i.e. no Sample Transform compositing because it happens\n        //     after decoding all tiles).\n        // Otherwise, we will use |tiles.count| decoder instances (one instance for each tile).\n        const avifBool canUseSingleCodecInstance =\n            ((data->tiles.count == 1) || (decoder->imageCount == 1 && avifTilesCanBeDecodedWithSameCodecInstance(data))) &&\n            data->sampleTransformNumInputImageItems == 0;\n        if (canUseSingleCodecInstance) {\n            AVIF_CHECKRES(avifCodecCreateInternal(decoder->codecChoice, &decoder->data->tiles.tile[0], &decoder->diag, &data->codec));\n            for (unsigned int i = 0; i < decoder->data->tiles.count; ++i) {\n                decoder->data->tiles.tile[i].codec = data->codec;\n            }\n        } else {\n            for (unsigned int i = 0; i < decoder->data->tiles.count; ++i) {\n                avifTile * tile = &decoder->data->tiles.tile[i];\n                AVIF_CHECKRES(avifCodecCreateInternal(decoder->codecChoice, tile, &decoder->diag, &tile->codec));\n            }\n        }\n    }\n    return AVIF_RESULT_OK;\n}\n\n','// One shared topology predicate for native admission and codec creation.\nstatic avifBool avifDecoderCanShareNativeCodec(const avifDecoder * decoder)\n{\n    const avifDecoderData * data = decoder->data;\n    return ((data->tiles.count == 1) || (decoder->imageCount == 1 && avifTilesCanBeDecodedWithSameCodecInstance(data))) &&\n           data->sampleTransformNumInputImageItems == 0;\n}\n\nstatic avifResult avifDecoderCreateCodecs(avifDecoder * decoder)\n{\n    avifDecoderData * data = decoder->data;\n    avifDecoderDataResetCodec(data);\n\n    if (data->source == AVIF_DECODER_SOURCE_TRACKS) {\n        // In this case, we will use at most two codec instances (one for the color planes and one for the alpha plane).\n        // Gain maps are not supported.\n        AVIF_CHECKRES(avifCodecCreateInternal(decoder->codecChoice, &decoder->data->tiles.tile[0], &decoder->diag, &data->codec));\n        data->tiles.tile[0].codec = data->codec;\n        if (data->tiles.count > 1) {\n            AVIF_CHECKRES(avifCodecCreateInternal(decoder->codecChoice, &decoder->data->tiles.tile[1], &decoder->diag, &data->codecAlpha));\n            data->tiles.tile[1].codec = data->codecAlpha;\n        }\n    } else {\n        // In this case, we will use one codec instance when there is only one tile or when all of the following conditions are\n        // met:\n        //   - The image must have exactly one layer (i.e. decoder->imageCount == 1).\n        //   - All the tiles must have the same operating point (because the codecs take operating point once at initialization\n        //     and do not allow it to be changed later).\n        //   - All the tiles must have the same value for allLayers (because the codecs take allLayers once at initialization\n        //     and do not allow it to be changed later).\n        //   - If the image has a single tile, it must not have a single tile alpha plane (in this case we will steal the planes\n        //     from the decoder, so we cannot use the same decoder for both the color and the alpha planes).\n        //   - All tiles have the same type (AV1 or AV2).\n        //   - No tile buffer access after another tile was decoded (i.e. no Sample Transform compositing because it happens\n        //     after decoding all tiles).\n        // Otherwise, we will use |tiles.count| decoder instances (one instance for each tile).\n        const avifBool canUseSingleCodecInstance =\n            avifDecoderCanShareNativeCodec(decoder);\n        if (canUseSingleCodecInstance) {\n            AVIF_CHECKRES(avifCodecCreateInternal(decoder->codecChoice, &decoder->data->tiles.tile[0], &decoder->diag, &data->codec));\n            for (unsigned int i = 0; i < decoder->data->tiles.count; ++i) {\n                decoder->data->tiles.tile[i].codec = data->codec;\n            }\n        } else {\n            for (unsigned int i = 0; i < decoder->data->tiles.count; ++i) {\n                avifTile * tile = &decoder->data->tiles.tile[i];\n                AVIF_CHECKRES(avifCodecCreateInternal(decoder->codecChoice, tile, &decoder->diag, &tile->codec));\n            }\n        }\n    }\n    return AVIF_RESULT_OK;\n}\n\n// Native admission inspects the exact instances avifDecoderCreateCodecs\n// will create. No codec or pixel allocation is performed by these helpers.\nuint32_t avifDecoderNativeCodecCount(const avifDecoder * decoder);\nuint64_t avifDecoderNativeCodecWorkPixels(const avifDecoder * decoder);\nuint64_t avifDecoderNativeCodecTileBudget(const avifDecoder * decoder);\nuint32_t avifDecoderNativeCodecCount(const avifDecoder * decoder)\n{\n    if (!decoder || !decoder->data || !decoder->data->tiles.count) return 0;\n    const avifDecoderData * data = decoder->data;\n    if (data->source == AVIF_DECODER_SOURCE_TRACKS) return 1u + (data->tiles.count > 1u);\n    return avifDecoderCanShareNativeCodec(decoder) ? 1u : data->tiles.count;\n}\n\nstatic uint64_t avifNativeCodecTileGeometry(const avifTile * tile, avifBool tileBudget)\n{\n    const uint64_t width = tile->width, height = tile->height;\n    if (!width || !height) return UINT64_MAX;\n    if (tileBudget) {\n        const uint64_t cols = AVIF_MIN(UINT64_C(64), (width + 63) / 64);\n        const uint64_t rows = AVIF_MIN(UINT64_C(64), (height + 63) / 64);\n        return cols * rows;\n    }\n    const uint64_t alignedWidth = (width + 127) & ~UINT64_C(127);\n    const uint64_t alignedHeight = (height + 127) & ~UINT64_C(127);\n    if (alignedHeight > UINT64_MAX / alignedWidth) return UINT64_MAX;\n    return alignedWidth * alignedHeight;\n}\n\nstatic uint64_t avifDecoderNativeCodecGeometry(const avifDecoder * decoder, avifBool tileBudget)\n{\n    if (!decoder || !decoder->data || !decoder->data->tiles.count) return 0;\n    const avifDecoderData * data = decoder->data;\n    const avifBool tracks = data->source == AVIF_DECODER_SOURCE_TRACKS;\n    const avifBool shared = !tracks && avifDecoderCanShareNativeCodec(decoder);\n    const uint32_t count = tracks ? AVIF_MIN(data->tiles.count, 2u) : data->tiles.count;\n    uint64_t total = 0;\n    for (uint32_t i = 0; i < count; ++i) {\n        const uint64_t value = avifNativeCodecTileGeometry(&data->tiles.tile[i], tileBudget);\n        if (value == UINT64_MAX) return UINT64_MAX;\n        if (shared) total = AVIF_MAX(total, value);\n        else {\n            if (value > UINT64_MAX - total) return UINT64_MAX;\n            total += value;\n        }\n    }\n    return total;\n}\n\nuint64_t avifDecoderNativeCodecWorkPixels(const avifDecoder * decoder)\n{\n    return avifDecoderNativeCodecGeometry(decoder, AVIF_FALSE);\n}\nuint64_t avifDecoderNativeCodecTileBudget(const avifDecoder * decoder)\n{\n    return avifDecoderNativeCodecGeometry(decoder, AVIF_TRUE);\n}\n\n')
